I=G['Demo pair 1 input']; O=G['Demo pair 1 output']
H,W=len(I),len(I[0])
# find exact mapping of O rows to I rows with reverse check per row
m=[]
for i in range(24):
    for j in range(H):
        if O[i][:W]==I[j]: m.append((i,j))
print(m)
# also half-row equalities? print which I rows (or reversed) each O full row equals
fulls=[tuple(r) for r in O]
cands=[]
for i,r in enumerate(fulls):
    match=None
    for j in range(H):
        x=I[j]; y=x[::-1]
        if tuple(x)==r[:W] or tuple(y)==r[:W]: match=(j,'fwd' if tuple(x)==r[:W] else 'rev')
    cands.append((i,match))
print(cands)
